const norm = (s) => s.replace(/\r\n/g, '\n');
const sha = (s) => createHash('sha256').update(norm(s), 'utf8').digest('hex');
const bad = [];
for (const f of FILES) {
  if (f.before === null) {
    if (existsSync(f.path)) bad.push(`${f.path}: уже есть (патч уже применён?)`);
    continue;
  }
  if (!existsSync(f.path)) { bad.push(f.after === null ? `${f.path}: уже удалён этим патчем` : `${f.path}: нет файла`); continue; }
  const h = sha(readFileSync(f.path, 'utf8'));
  if (f.after !== null && h === f.after) bad.push(`${f.path}: уже изменён этим патчем`);
  else if (h !== f.before) bad.push(`${f.path}: файл не тот, что ожидался (менялся?)`);
}
if (bad.length) {
  console.error('Отказ — ничего не изменено:\n' + bad.map((b) => '  ' + b).join('\n'));
  process.exit(1);
}
for (const f of FILES) {
  if (f.after === null) { rmSync(f.path); console.log(`− ${f.path}`); continue; }
  let text = f.content;
  if (f.before !== null && readFileSync(f.path, 'utf8').includes('\r\n')) text = text.replace(/\n/g, '\r\n');
  mkdirSync(dirname(f.path), { recursive: true });
  writeFileSync(f.path, text, 'utf8');
  console.log(`${f.before === null ? '+' : '·'} ${f.path}`);
}
console.log('\nГотово.');
